//! Settings generated by Nix and passed with `--config <path>`.

use serde::Deserialize;

#[derive(Debug, Clone, Deserialize)]
#[serde(rename_all = "camelCase", default)]
pub struct Config {
    /// Pi model for name generation; `--model` is omitted when unset.
    pub model: Option<String>,
    /// Pi thinking level for name generation; `--thinking` is omitted when unset.
    pub thinking: Option<String>,
    /// Pathspecs limiting the diff sent to Pi.
    pub diff_pathspecs: Vec<String>,
    pub fuzzy_finder: String,
    pub git: String,
    pub gh: String,
    pub tmux: String,
    pub patch: String,
    pub petname: String,
}

impl Default for Config {
    fn default() -> Self {
        Self {
            model: None,
            thinking: None,
            diff_pathspecs: Vec::new(),
            fuzzy_finder: "fzf".into(),
            git: "git".into(),
            gh: "gh".into(),
            tmux: "tmux".into(),
            patch: "patch".into(),
            petname: "petname".into(),
        }
    }
}

impl Config {
    pub fn load(path: &str) -> Result<Self, String> {
        let text = std::fs::read_to_string(path).map_err(|e| format!("{path}: {e}"))?;
        serde_json::from_str(&text).map_err(|e| format!("{path}: {e}"))
    }
}
